"""Verify the restored production and retained, source-matched regression gate."""
import hashlib
import json
from pathlib import Path
import subprocess
import xml.etree.ElementTree as ET

from runtime_identity import tree_digest, tree_files

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
MODULE = ROOT / 'core/sail/lmdb'
TEST = 'core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializerTest.java'
PRODUCTION = 'core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializer.java'
EXPECTED_HEAD = '15fe7d5011d27d31d76436238363ee3f34b3ba50'
EXPERIMENT_ONLY = {
    'sparseFactorPagesReuseWithinCompactPageBudget',
    'refusedFactorPagePromotionPreservesCellsAndRetriesAfterMemoryRelease',
}
RETAINED_NEW = {
    'factorPagePromotionPreservesAllLongPositionCells',
    'factorPageReusesClearedCellAfterSamePositionWitnessReplacement',
    'factorPageRetirementAndLedgerCloseReleaseMixedPageRepresentations',
}


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def cases(folder):
    return {(suite.attrib['name'], case.attrib['name'])
            for path in folder.glob('TEST-*.xml')
            for suite in [ET.parse(path).getroot()]
            for case in suite.findall('testcase')}


def main():
    destination = HERE / 'selected-source-verification.json'
    if destination.exists():
        raise RuntimeError('Refusing to replace selected-source evidence')
    baseline = json.loads((HERE / 'baseline/sources.json').read_text())
    current = {path.relative_to(ROOT).as_posix(): sha(path)
               for path in sorted((MODULE / 'src').rglob('*')) if path.is_file()}
    stage = HERE / 'validation/selected-original'
    tested_before = json.loads((stage / 'sources-before.json').read_text())
    tested_after = json.loads((stage / 'sources-after.json').read_text())
    result = json.loads((stage / 'results.json').read_text())
    assert result == dict(classes=8, tests=106, failures=0, errors=0, skipped=0), result
    assert current == tested_before == tested_after
    assert current.keys() == baseline.keys()
    changed = [path for path in baseline if baseline[path] != current[path]]
    assert changed == [TEST], changed
    assert current[PRODUCTION] == 'cb0749719313b85c8cd134b6c03085f712915188f0e53333cbd46e19e2f0f96e'

    control_stage = ROOT / 'result-coordinate-evidence/namespace-followup/validation/original-frame-characterization'
    prior = cases(control_stage / 'surefire-reports')
    candidate = cases(HERE / 'validation/compact-correctness/surefire-reports')
    selected = cases(stage / 'surefire-reports')
    assert len(prior) == 103 and len(candidate) == 108 and len(selected) == 106
    assert prior <= selected <= candidate
    assert {name for _, name in candidate - selected} == EXPERIMENT_ONLY
    assert {name for _, name in selected - prior} == RETAINED_NEW

    original_manifest = json.loads((HERE / 'baseline/runtime-manifest.json').read_text())
    original_files = tree_files(Path(original_manifest[1]['path']))
    compiled_files = tree_files(MODULE / 'target/classes')
    assert compiled_files == original_files
    production_tree = tree_digest(compiled_files)
    assert production_tree == original_manifest[1]['sha256']
    assert production_tree == 'f822ad378729e2ebdd5c7e91d2420e9dbf1eb92aab382e76c35fba00989eab8c'
    preserved = json.loads((HERE / 'experimental-candidate/preservation.json').read_text())
    for relative, digest in preserved['sourceHashes'].items():
        assert sha(HERE / 'experimental-candidate/sources' / relative) == digest
    assert sha(HERE / 'experimental-candidate/core-delta.patch') == preserved['coreDeltaSha256']
    head = subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip()
    assert head == EXPECTED_HEAD
    subprocess.run(['git', 'diff', '--check'], cwd=ROOT, check=True)

    receipt = {
        'format': 1, 'verified': True, 'selectedProduction': 'original',
        'head': head, 'moduleSourceFiles': len(current),
        'changedModuleSourcePathsSincePhaseBaseline': changed,
        'currentSourcesEqualSuccessfulGateBeforeAndAfter': True,
        'allProductionSourcesEqualPhaseBaseline': True,
        'restoredMaterializerSha256': current[PRODUCTION],
        'selectedTestSha256': current[TEST],
        'compiledProductionFiles': len(compiled_files),
        'compiledProductionTreeSha256': production_tree,
        'compiledProductionExactlyMatchesOriginalFrozenRuntime': True,
        'selectedValidation': result,
        'allPrior103TestIdentitiesRetained': True,
        'retainedNewTests': sorted(RETAINED_NEW),
        'compactOnlyTestsPreservedOutsideSelectedSource': sorted(EXPERIMENT_ONLY),
        'candidateSourceAndPatchPreserved': True,
        'validationSourceMapSha256': sha(stage / 'sources-after.json'),
        'validationResultsSha256': sha(stage / 'results.json'),
        'verifierSha256': sha(Path(__file__)),
    }
    destination.write_text(json.dumps(receipt, indent=2) + '\n')
    print(json.dumps(receipt))


if __name__ == '__main__':
    main()
